-- Generated by tools/boss_ladder.py: the ten tiers and the bosses of tiers 2-10. Safe to run again.
on conflict (tier) do update set n = excluded.n, blurb = excluded.blurb, drop_chance = excluded.drop_chance, pity = excluded.pity;
on conflict (id) do update set n = excluded.n, blurb = excluded.blurb, art = excluded.art, hours = excluded.hours, coin_per_action = excluded.coin_per_action,
  victory_bonus = excluded.victory_bonus, phases = excluded.phases, sort = excluded.sort, tier = excluded.tier;
on conflict (id) do update set tier = excluded.tier, slot = excluded.slot, bar = excluded.bar, raid = excluded.raid;
