insert into public.raid_tiers (tier, n, blurb, drop_chance, pity) values
  (1, 'The Valley', 'Trouble close to home: the mill, the quarry, the pond and the cove.', 0.3, 4),
  (2, 'The Wild Woods', 'Past the Mossy Woods the trees get older, and so do the things that live under them.', 0.26, 5),
  (3, 'The Old Forest', 'Deep in the woods the trees are older than the valley, and they remember everything.', 0.22, 6),
  (4, 'The Deep Caves', 'Below the bottom of the Mine there are caves nobody has mapped.', 0.19, 7),
  (5, 'The Fire Below', 'Deeper still, the rock gets warm, then hot, then it glows.', 0.16, 8),
  (6, 'The Far Shore', 'Out past the cove, where the rocks go down into deep water.', 0.13, 9),
  (7, 'The Open Sea', 'Beyond the last island the water is deep enough to hide anything.', 0.11, 10),
  (8, 'The Snowfields', 'Above the highlands the snow never melts and the wind never stops.', 0.09, 12),
  (9, 'The Storm Peaks', 'Where the mountains stab the clouds and the thunder lives.', 0.07, 14),
  (10, 'The Roof of the World', 'The highest place there is. Only the oldest and strongest live here.', 0.05, 16)
insert into public.raid_boss_defs (id, n, blurb, art, hours, coin_per_action, victory_bonus, phases, sort, tier) values
  ('thornback_boar', 'The Thornback Boar', 'A boar the size of a hay cart has been tearing up the orchard rows at night, and nothing will stand in its way.', 4, 48, 18, 500, '[{"n": "Tracks in the Orchard", "text": "Hoofprints as wide as buckets lead into the trees. Head it off before the orchard is ruined.", "might": 500, "magic": 380}, {"n": "The Charge", "text": "It comes crashing through the hedges. Stand firm and strike as it passes.", "might": 650, "magic": 490}, {"n": "Cornered in the Bracken", "text": "Backed into the ferns, it lowers those great tusks. Finish it!", "might": 800, "magic": 600}]'::jsonb, 5, 2),
  ('hollow_oak_bear', 'The Old Bear of Hollow Oak', 'The oldest bear in the woods has woken hungry, and it has found the beehives.', 5, 48, 20, 580, '[{"n": "Honey on the Wind", "text": "It sniffs out every hive in the valley. Draw it away from the bees.", "might": 490, "magic": 490}, {"n": "The Swipe", "text": "One paw flattens a fence. Keep your distance and keep hitting.", "might": 640, "magic": 640}, {"n": "Back to the Hollow", "text": "It turns for its den in the old oak. One last push before it hides.", "might": 780, "magic": 780}]'::jsonb, 6, 2),
  ('moss_troll', 'The Moss Troll', 'Something big and green and covered in moss has moved in under the old bridge, and it wants a toll.', 6, 48, 22, 660, '[{"n": "The Toll", "text": "It blocks the bridge and holds out a huge mossy hand. Nobody pays.", "might": 320, "magic": 420}, {"n": "Moss and Mud", "text": "It hurls clods of mud and moss. Dry it out with fire and sun.", "might": 410, "magic": 540}, {"n": "Regrowing", "text": "Every cut grows back green. Burn the moss before it heals.", "might": 510, "magic": 670}, {"n": "Off the Bridge", "text": "Knock it into the stream and the bridge is yours again!", "might": 600, "magic": 800}]'::jsonb, 7, 2),
  ('weeping_willow', 'The Weeping Willow', 'A willow by the black pool has started walking, and wherever it goes the flowers droop.', 7, 48, 27, 850, '[{"n": "The Drooping Fields", "text": "Its branches trail over the crops and they wilt. Cut it back.", "might": 630, "magic": 840}, {"n": "Tears of Sap", "text": "It weeps a sticky sap that holds you fast. Break free and strike.", "might": 820, "magic": 1090}, {"n": "Roots in the Pool", "text": "It sinks its roots into the black pool. Pull it out before it takes hold.", "might": 1010, "magic": 1340}]'::jsonb, 8, 3),
  ('antler_king', 'The Antler King', 'A great stag with a crown of antlers rules the deep forest, and it has decided the valley is part of its kingdom.', 8, 48, 30, 970, '[{"n": "The Herald", "text": "Its call echoes through the trees and every deer in the forest answers.", "might": 940, "magic": 710}, {"n": "The Crown of Antlers", "text": "It lowers its crown and charges. Catch the antlers and hold!", "might": 1220, "magic": 920}, {"n": "The Forest Rises", "text": "Vines and branches rise to defend their king. Cut your way through.", "might": 1500, "magic": 1130}]'::jsonb, 9, 3),
  ('greatwood', 'The Greatwood', 'The oldest tree in the forest has pulled up its roots and is walking toward the farms, one slow step a day.', 9, 48, 32, 1100, '[{"n": "The Ground Shakes", "text": "Every step it takes cracks the earth. Slow it down at the forest edge.", "might": 620, "magic": 620}, {"n": "Falling Leaves", "text": "Leaves as big as doors come spinning down. Shelter the village and strike back.", "might": 800, "magic": 800}, {"n": "Roots Like Rivers", "text": "Its roots burst up through the fields. Hack them back before they reach the farms.", "might": 990, "magic": 990}, {"n": "The Heartwood", "text": "A golden light glows deep in its trunk. Aim for the heart of the forest!", "might": 1170, "magic": 1170}]'::jsonb, 10, 3),
  ('cave_weaver', 'The Cave Weaver', 'Miners keep finding their tunnels sealed with silk as thick as rope. Something down there is weaving.', 10, 48, 40, 1420, '[{"n": "Silk in the Tunnels", "text": "Every passage is webbed shut. Cut a way through.", "might": 1410, "magic": 1060}, {"n": "Eyes in the Dark", "text": "Eight eyes shine in the lantern light. Keep your lights high and strike.", "might": 1830, "magic": 1380}, {"n": "The Great Web", "text": "It waits at the heart of its web. Bring it down!", "might": 2250, "magic": 1700}]'::jsonb, 11, 4),
  ('great_burrower', 'The Great Burrower', 'A worm as long as the village street is chewing through the rock under the fields, and the wells are running dry.', 11, 48, 45, 1640, '[{"n": "The Rumbling", "text": "The ground hums and the wells go dry. Find where it is digging.", "might": 1190, "magic": 1570}, {"n": "It Surfaces", "text": "It bursts up through the cellar floors. Drive it back down!", "might": 1540, "magic": 2050}, {"n": "Deep Tunnel", "text": "Follow it into the dark and finish it at the bottom.", "might": 1900, "magic": 2520}]'::jsonb, 12, 4),
  ('amethyst_golem', 'The Amethyst Golem', 'In a cave full of purple crystal, the crystal stood up.', 12, 48, 49, 1850, '[{"n": "A Glittering Cave", "text": "Every crystal hums with light. Find the one that moves.", "might": 1040, "magic": 1040}, {"n": "Shards", "text": "It sheds razor shards with every swing. Shield up and keep striking.", "might": 1350, "magic": 1350}, {"n": "Crystal Light", "text": "It flares so bright you can barely see. Strike at the glow.", "might": 1660, "magic": 1660}, {"n": "The Core", "text": "Its heart is one perfect gem. Crack it!", "might": 1970, "magic": 1970}]'::jsonb, 13, 4),
  ('ember_salamander', 'The Ember Salamander', 'A salamander made of living fire has climbed up from the deep, and the Mine is too hot to work.', 13, 48, 61, 2390, '[{"n": "Heat in the Tunnels", "text": "The air shimmers and the walls are hot to touch. Douse the flames.", "might": 1780, "magic": 2360}, {"n": "Tail of Fire", "text": "It lashes a tail of flame through the dark. Dodge and strike.", "might": 2320, "magic": 3070}, {"n": "Back to the Fire", "text": "It flees for the lava. Cut it off before it gets home.", "might": 2850, "magic": 3780}]'::jsonb, 14, 5),
  ('magma_golem', 'The Magma Golem', 'Something made of cooling lava has started pounding on the walls at the bottom of the Mine.', 14, 48, 67, 2750, '[{"n": "Knocking", "text": "Deep, slow knocks from below. Then the wall breaks.", "might": 1780, "magic": 1340}, {"n": "Molten Fists", "text": "Its fists drip burning rock. Crack its crust while it cools.", "might": 2310, "magic": 1740}, {"n": "The Glow Rises", "text": "It heats up again, brighter and angrier. Keep at it!", "might": 2850, "magic": 2150}, {"n": "Stone Cold", "text": "Cool it down for good and the Mine is safe again.", "might": 3380, "magic": 2550}]'::jsonb, 15, 5),
  ('hoard_dragon', 'The Hoard Dragon', 'At the very bottom of the world a golden dragon sleeps on a mountain of treasure. Somebody woke it.', 15, 48, 73, 3110, '[{"n": "A Hill of Gold", "text": "The treasure shifts and breathes. It is not a hill.", "might": 1260, "magic": 1260}, {"n": "Wings in the Dark", "text": "It spreads its wings and fills the cavern. Hold your ground.", "might": 1640, "magic": 1640}, {"n": "Dragonfire", "text": "Fire pours through the tunnels. Shield the miners and strike back.", "might": 2020, "magic": 2020}, {"n": "Guarding the Hoard", "text": "It coils around its gold and will not move. Pry it loose!", "might": 2400, "magic": 2400}, {"n": "The Last Flame", "text": "One last roar shakes the whole Mine. Finish it!", "might": 2780, "magic": 2780}]'::jsonb, 16, 5),
  ('crab_king', 'The Crab King', 'A crab as big as a fishing boat has claimed the beach, and it pinches anyone who comes near.', 16, 60, 91, 4010, '[{"n": "Claws on the Sand", "text": "It scuttles sideways along the tideline, snapping at everything.", "might": 3970, "magic": 2990}, {"n": "The Shell", "text": "Its shell turns every blow. Find the gaps!", "might": 5160, "magic": 3890}, {"n": "Low Tide", "text": "Stranded by the tide, it is slow at last. Strike now!", "might": 6350, "magic": 4790}]'::jsonb, 17, 6),
  ('tidecaller', 'The Tidecaller', 'A figure made of seawater walks out of the waves with a trident, and the tide follows it.', 17, 60, 100, 4620, '[{"n": "The Sea Rises", "text": "The tide comes in and keeps coming. Hold back the water.", "might": 2250, "magic": 2990}, {"n": "Waves on Command", "text": "It raises a wave higher than the watchtower. Break it!", "might": 2930, "magic": 3880}, {"n": "The Trident", "text": "Lightning crackles along its trident. Disarm it.", "might": 3610, "magic": 4780}, {"n": "Back into the Sea", "text": "Without its trident it is only water. Drive it back into the waves!", "might": 4280, "magic": 5680}]'::jsonb, 18, 6),
  ('sea_serpent', 'The Sea Serpent', 'Fishermen have seen a long blue back rolling in the bay. Now it has coiled around the jetty.', 18, 60, 109, 5220, '[{"n": "Coils in the Bay", "text": "Its long body loops through the water. Find its head.", "might": 2120, "magic": 2120}, {"n": "Squeeze", "text": "It tightens around the jetty and the timbers groan. Make it let go!", "might": 2760, "magic": 2760}, {"n": "The Bite", "text": "It strikes like lightning from the water. Stand firm.", "might": 3390, "magic": 3390}, {"n": "Rising Tide", "text": "It drags the tide up the beach with it. Hold the line.", "might": 4030, "magic": 4030}, {"n": "Into the Deep", "text": "It dives for deep water. One last strike before it goes!", "might": 4660, "magic": 4660}]'::jsonb, 19, 6),
  ('wandering_isle', 'The Wandering Isle', 'An island drifted into the bay overnight. It has a castle on it, and it is blinking.', 19, 60, 137, 6740, '[{"n": "Land Ho", "text": "A new island sits in the bay. Then it moves.", "might": 6660, "magic": 5030}, {"n": "The Castle on its Back", "text": "Things live in the old castle, and they are not friendly. Clear them out.", "might": 8660, "magic": 6540}, {"n": "It Dives", "text": "It starts to sink, castle and all. Strike before it is gone!", "might": 10660, "magic": 8040}]'::jsonb, 20, 7),
  ('leviathan', 'The Leviathan', 'A sea dragon longer than the village has surfaced off the point, and its wake swamps the boats.', 20, 60, 150, 7760, '[{"n": "A Shadow Under the Boats", "text": "Something huge passes under the fishing fleet. Get the boats home.", "might": 3790, "magic": 5020}, {"n": "Rising", "text": "It rises out of the sea, scales streaming. Strike at its belly.", "might": 4920, "magic": 6520}, {"n": "The Whirlpool", "text": "It circles until the sea turns into a whirlpool. Hold on and fight.", "might": 6060, "magic": 8030}, {"n": "Back to the Depths", "text": "Wounded, it sinks away. Make sure it never comes back.", "might": 7190, "magic": 9540}]'::jsonb, 21, 7),
  ('kraken', 'The Kraken', 'Out at sea the water boiled, and then the arms came up. Dozens of them.', 21, 60, 164, 8770, '[{"n": "Arms from the Deep", "text": "Huge arms reach out of the water and grab at the boats.", "might": 3560, "magic": 3560}, {"n": "Ink", "text": "The sea goes black with ink. Fight by lantern light.", "might": 4630, "magic": 4630}, {"n": "Crushing Grip", "text": "It drags the jetty toward the deep. Cut it free!", "might": 5700, "magic": 5700}, {"n": "The Eye", "text": "One great eye opens beneath the waves. Aim for it!", "might": 6770, "magic": 6770}, {"n": "Sinking Down", "text": "It lets go at last. Drive it back into the dark!", "might": 7840, "magic": 7840}]'::jsonb, 22, 7),
  ('snow_yeti', 'The Snow Yeti', 'Huge footprints in the snow, and the sheep keep going missing.', 22, 60, 205, 11330, '[{"n": "Footprints", "text": "They lead up the mountain, and they are getting bigger.", "might": 7530, "magic": 5680}, {"n": "The Avalanche", "text": "It roars and the snow slides. Dig out and fight back.", "might": 9790, "magic": 7380}, {"n": "In its Cave", "text": "Corner it in its ice cave and finish it.", "might": 12040, "magic": 9090}, {"n": "The Long Howl", "text": "It howls until the mountain shakes. Hold steady!", "might": 14300, "magic": 10790}]'::jsonb, 23, 8),
  ('ice_wyrm', 'The Ice Wyrm', 'A dragon of blue ice has frozen the mountain pass, and nobody can get through.', 23, 60, 226, 13030, '[{"n": "The Frozen Pass", "text": "The road is a wall of ice. Melt a way through.", "might": 4610, "magic": 6110}, {"n": "Frost Breath", "text": "It breathes a blizzard. Keep the fires burning.", "might": 5990, "magic": 7950}, {"n": "Ice Armour", "text": "It grows armour of ice over every wound. Break it!", "might": 7380, "magic": 9780}, {"n": "The Thaw", "text": "Melt its heart and the pass is open again.", "might": 8760, "magic": 11610}, {"n": "Meltwater", "text": "It crumbles into the river. Make sure it stays there.", "might": 10150, "magic": 13450}]'::jsonb, 24, 8),
  ('frost_giant', 'The Frost Giant', 'A giant made of ice and old snow has come down from the peaks with a spear as long as a tree.', 24, 60, 246, 14730, '[{"n": "Giant Steps", "text": "Each step leaves a frozen crater. Stop it before it reaches the farms.", "might": 5980, "magic": 5980}, {"n": "The Spear", "text": "It hurls its spear and the ground cracks. Dodge!", "might": 7780, "magic": 7780}, {"n": "Winter Comes", "text": "Everything it touches freezes. Warm the village and fight on.", "might": 9580, "magic": 9580}, {"n": "Kneeling Giant", "text": "Bring it to its knees with everything you have.", "might": 11370, "magic": 11370}, {"n": "The Melt", "text": "It starts to melt into the snow. One last blow!", "might": 13170, "magic": 13170}]'::jsonb, 25, 8),
  ('storm_griffin', 'The Storm Griffin', 'A griffin with feathers like storm clouds nests on the highest crag, and it hunts by lightning.', 25, 72, 308, 19040, '[{"n": "Shadow in the Clouds", "text": "Something circles above the peaks. Then it dives.", "might": 12650, "magic": 9540}, {"n": "Talons", "text": "It swoops at anyone on the high paths. Strike as it passes.", "might": 16440, "magic": 12400}, {"n": "The Nest", "text": "Climb to its nest above the clouds.", "might": 20240, "magic": 15270}, {"n": "Grounded", "text": "Clip its wings and bring it down!", "might": 24030, "magic": 18130}]'::jsonb, 26, 9),
  ('storm_drake', 'The Storm Drake', 'A blue dragon crackling with lightning rides the storms over the peaks, and the storms are getting closer.', 26, 72, 338, 21890, '[{"n": "Thunder on the Peaks", "text": "The storm rolls closer every hour. Get ready.", "might": 7750, "magic": 10270}, {"n": "Lightning", "text": "It calls lightning down on the valley. Ground it!", "might": 10070, "magic": 13350}, {"n": "The Eye of the Storm", "text": "Fight it in the calm heart of the storm.", "might": 12400, "magic": 16430}, {"n": "Sky on Fire", "text": "The clouds crackle from end to end. Keep your heads down and strike.", "might": 14720, "magic": 19510}, {"n": "The Storm Breaks", "text": "Drive it off and let the sun back in!", "might": 17040, "magic": 22590}]'::jsonb, 27, 9),
  ('thunder_giant', 'The Thunder Giant', 'A giant in armour that rings like thunder has come to claim the peaks, and the whole mountain shakes.', 27, 72, 369, 24750, '[{"n": "The Mountain Shakes", "text": "Every blow of its hammer shakes loose a rockslide.", "might": 10050, "magic": 10050}, {"n": "Thunder Armour", "text": "Its armour sparks with every hit. Find the gaps.", "might": 13070, "magic": 13070}, {"n": "The War Cry", "text": "It roars and the clouds split. Hold steady.", "might": 16090, "magic": 16090}, {"n": "Hammer Down", "text": "It brings its hammer down on the pass. Stop it!", "might": 19100, "magic": 19100}, {"n": "Fallen Thunder", "text": "Bring the giant down and the storm goes with it.", "might": 22120, "magic": 22120}]'::jsonb, 28, 9),
  ('elder_phoenix', 'The Elder Phoenix', 'A bird of living fire has lit up the sky over the peaks. Every time it falls, it rises again.', 28, 72, 461, 31980, '[{"n": "A Second Sun", "text": "The sky glows red over the mountains. Something is burning up there.", "might": 11620, "magic": 15400}, {"n": "Wings of Fire", "text": "It sweeps over the peaks and the snow turns to steam.", "might": 15110, "magic": 20030}, {"n": "Ashes", "text": "It falls in a heap of ashes. Then the ashes stir.", "might": 18590, "magic": 24650}, {"n": "Reborn", "text": "It rises again, brighter than before. Strike faster!", "might": 22080, "magic": 29270}, {"n": "The Last Ember", "text": "Put out its last ember before it can rise again!", "might": 25570, "magic": 33890}]'::jsonb, 29, 10),
  ('sky_titan', 'The Sky Titan', 'On the very top of the world stands a giant so tall its head is in the clouds. It has noticed the valley.', 29, 72, 507, 36780, '[{"n": "Above the Clouds", "text": "A shadow falls across the whole valley.", "might": 17250, "magic": 13020}, {"n": "The Spear of the Sky", "text": "It hurls a spear that splits a mountain. Shield the village!", "might": 22430, "magic": 16920}, {"n": "Climbing the Titan", "text": "Climb its armour and strike where it cannot reach.", "might": 27600, "magic": 20820}, {"n": "The Titan Stumbles", "text": "It sways on the edge of the world. Push!", "might": 32780, "magic": 24730}, {"n": "The Long Fall", "text": "Bring the titan down from the roof of the world!", "might": 37960, "magic": 28630}]'::jsonb, 30, 10),
  ('white_dragon', 'The White Dragon', 'The oldest dragon of all sleeps on the roof of the world. When it wakes, winter comes to every valley at once.', 30, 72, 554, 41580, '[{"n": "The Long Winter", "text": "Snow falls in summer. Something old is waking.", "might": 10160, "magic": 10160}, {"n": "Wings Over the Valley", "text": "It flies over every farm and the fields freeze. Hold on.", "might": 13210, "magic": 13210}, {"n": "Frost and Fury", "text": "It lands on the peaks and the mountain shakes. Climb to meet it.", "might": 16260, "magic": 16260}, {"n": "The Dragon Speaks", "text": "Its voice rolls like an avalanche. Do not listen. Strike!", "might": 19300, "magic": 19300}, {"n": "Scales Like Glaciers", "text": "Its scales turn every blade. Find the soft places.", "might": 22350, "magic": 22350}, {"n": "The Breath of Winter", "text": "It breathes the whole of winter at the valley. Stand together!", "might": 25400, "magic": 25400}, {"n": "Spring Returns", "text": "One last push, and the sun comes back to the valley.", "might": 28450, "magic": 28450}]'::jsonb, 31, 10)
